(async()=>{'use strict';const M=SpaceFoxM,R=SpaceFoxMR,D=SpaceFoxMarkerData,L=SpaceFoxLayoutData,$=s=>document.querySelector(s),final=await(await fetch('final-selection.json')).json();let family=0,sceneIndex=0,mode='overview';const old=M.controls();
const short=structuredClone(D.hero),launch=L.launches.falcon;short.id='comparison-short-ru';short.fixture.point=launch.point;short.fixture.purpose={full:'Связь',displayLabel:'Связь'};short.countdown.displayLabel='T−2ч 14м';
const longer=lang=>D.scenes.filter(s=>s.language===lang&&s.fixture.point).slice().sort((a,b)=>Array.from(b.fixture.operator.displayLabel).length-Array.from(a.fixture.operator.displayLabel).length||Array.from(b.fixture.purpose.displayLabel).length-Array.from(a.fixture.purpose.displayLabel).length||a.id.localeCompare(b.id))[0];const scenes=[short,longer('ru'),longer('en')];let stats;
function sample(c,s){const face=R.render(c,s);$('#bed').replaceChildren(face);const box=face.getBoundingClientRect(),rect=e=>{const b=e.getBoundingClientRect(),v=getComputedStyle(e);return{x:b.x-box.x,y:b.y-box.y,w:b.width,h:b.height,cx:b.x-box.x+b.width/2,cy:b.y-box.y+b.height/2,font:v.fontFamily,fontSize:parseFloat(v.fontSize),lineHeight:v.lineHeight,textAlign:v.textAlign,color:v.color,value:e.textContent};};return{labels:Object.fromEntries([...face.querySelectorAll('.label')].map(e=>[e.dataset.role,rect(e)])),mission:rect(face.querySelector('.mission')),fields:rect(face.querySelector('.field-row')),rocket:rect(face.querySelector('.rocket-image')),geography:rect(face.querySelector('.geography')),pin:[+face.querySelector('.geography').dataset.pinX,+face.querySelector('.geography').dataset.pinY],cue:face.querySelector('.launch-cue')?rect(face.querySelector('.launch-cue')):null};}
function measure(){const rows=[];for(let i=0;i<5;i++)for(const s of scenes){const a=sample(old[i],s),b=sample(final.candidates[i],s),required=Object.keys(a.labels),different=[];for(const role of required){const x=a.labels[role],y=b.labels[role];if(['x','y','w','h','fontSize'].some(k=>Math.abs(x[k]-y[k])>.02)||x.font!==y.font||x.color!==y.color||x.value!==y.value)different.push(role);}rows.push({family:final.candidates[i].family,scene:s.id,oldId:old[i].base.id,newId:final.candidates[i].id,baseEqual:JSON.stringify(old[i].base)===JSON.stringify(final.candidates[i].base),old:a,new:b,requiredTextDifferences:different,missionCenterOffsetFromTime:a.labels.rocket.cx-a.labels.time.cx,newCueCenterOffsetFromPin:b.cue?b.cue.cx-b.pin[0]:null});}$('#bed').replaceChildren();return{method:'Actual native390 DOM boxes/styles, identical scenes per pair; no reading-speed or aesthetic-score inference.',scenes,rows};}
function card(c,s,label){const a=document.createElement('article');a.className='card';const h=document.createElement('h2');h.textContent=label;const p=document.createElement('div');p.className='preview';p.append(R.render(c,s));a.append(h,p);return a;}
function paint(){document.body.className=mode;const s=scenes[sceneIndex];$('#mode').textContent=mode==='pair'?'Показать все пять':'Сравнить пару 390 px';$('#gallery').replaceChildren();if(mode==='pair'){$('#gallery').append(card(old[family],s,'Прошлый · '+D.names[old[family].base.id]+' ('+old[family].base.id+')'),card(final.candidates[family],s,'Новый · '+final.names[family]+' ('+final.candidates[family].id+')'));}else{for(const [i,c]of old.entries())$('#gallery').append(card(c,s,'Прошлый · '+D.names[c.base.id]));for(const [i,c]of final.candidates.entries())$('#gallery').append(card(c,s,'Новый · '+final.names[i]));}$('#status').textContent=(mode==='pair'?final.names[family]+' · 390×390':'Все пять · верхний ряд прошлый, нижний новый · 195×195')+' · одинаковые данные, свет и масштаб.';}
$('#family').replaceChildren(...final.names.map((name,i)=>{const o=document.createElement('option');o.value=i;o.textContent=name;return o;}));$('#family').onchange=()=>{family=+$('#family').value;mode='pair';paint();};$('#scene').onchange=()=>{sceneIndex=+$('#scene').value;paint();};$('#mode').onclick=()=>{mode=mode==='pair'?'overview':'pair';paint();};$('#exportCompare').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(stats,null,2)],{type:'application/json'}));a.download='whole-face-comparison.json';a.click();};
await Promise.all([...new Set(Object.values(SpaceFoxF.fonts))].map(f=>document.fonts.load(`600 80px '${f}'`)));await document.fonts.load("500 21px 'Noto Sans'",'Россия USA');await document.fonts.ready;stats=measure();paint();})();
